export type PullRequestCheckStatus = "passed" | "failed" | "running" | "pending" | "skipped"

export interface PullRequestCheck {
  /** Check name as the CI reports it, for example `ci / test (node 22)`. */
  name: string
  status: PullRequestCheckStatus
  /** Short result line, for example "3 tests failed". */
  description?: React.ReactNode
  /** Run time in ms, shown once the check finishes. */
  durationMs?: number
  /** Link to the check run. */
  href?: string
  /** Required checks gate Merge. Defaults to `true`. */
  required?: boolean
}

export function summarizeChecks(checks: ReadonlyArray<PullRequestCheck>) {
  let passed = 0
  let failed = 0
  let running = 0
  let pending = 0
  let skipped = 0
  let requiredFailed = 0
  let requiredWaiting = 0
  for (const check of checks) {
    const required = check.required !== false
    if (check.status === "passed") passed++
    else if (check.status === "failed") {
      failed++
      if (required) requiredFailed++
    } else if (check.status === "running") {
      running++
      if (required) requiredWaiting++
    } else if (check.status === "pending") {
      pending++
      if (required) requiredWaiting++
    } else skipped++
  }
  return { passed, failed, running, pending, skipped, requiredFailed, requiredWaiting }
}

const CHECK_ORDER: Record<PullRequestCheckStatus, number> = {
  failed: 0,
  running: 1,
  pending: 2,
  passed: 3,
  skipped: 4,
}

/** Failing checks first, then running, pending, passed and skipped. Stable inside a group. */
export function sortChecks(checks: ReadonlyArray<PullRequestCheck>) {
  return checks
    .map((check, index) => ({ check, index }))
    .sort((a, b) => CHECK_ORDER[a.check.status] - CHECK_ORDER[b.check.status] || a.index - b.index)
    .map((entry) => entry.check)
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type PullRequestStatus = "open" | "draft" | "merged" | "closed"

export interface PullRequestAuthor {
  name: string
  /** `agent` adds a quiet Agent label next to the name. */
  kind?: "agent" | "person"
  /** An avatar or provider mark, drawn at 16 px. */
  avatar?: React.ReactNode
}

export type DiffFileStatus = "added" | "modified" | "deleted" | "renamed"

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

/** What the list needs from a file. A `DiffFile` from chatcn-diff fits as is. */
interface ChangedFile {
  path: string
  oldPath?: string
  status: DiffFileStatus
  additions: number
  deletions: number
}

export type PullRequestReviewState = "approved" | "changes-requested" | "review-required" | "commented"

export interface PullRequestReview {
  state: PullRequestReviewState
  /** Who approved, requested changes, or is requested to review. */
  reviewers?: string[]
}

export type PullRequestMergeable = "ready" | "conflicts" | "blocked" | "unknown"

export interface PullRequestCardProps extends Omit<React.ComponentProps<"div">, "title"> {
  title: React.ReactNode
  number: number
  status: PullRequestStatus
  /** `owner/name`. */
  repo?: string
  /** Head branch. */
  branch?: string
  /** Base branch. Defaults to `main`. */
  baseBranch?: string
  author?: PullRequestAuthor
  /** Extra text in the meta line, for example "opened 4 min ago". */
  meta?: React.ReactNode
  /** Changed files. Shows the totals with the five-cell bar and an expandable file list. */
  files?: ChangedFile[]
  /** Totals when you do not have the file list. Ignored when `files` is set. */
  stats?: { files: number; additions: number; deletions: number }
  checks?: PullRequestCheck[]
  review?: PullRequestReview
  /** What the host reports about the merge. Defaults to `ready` for open pull requests. */
  mergeable?: PullRequestMergeable
  /** Words for `mergeable="blocked"` or `canMerge={false}`. Say how to unblock it. */
  blockedReason?: React.ReactNode
  /** Overrides the merge gate. `true` allows Merge even with pending checks or no review. */
  canMerge?: boolean
  /** The merge request is in flight. */
  merging?: boolean
  /** Why the last merge attempt failed. Shows Retry. */
  mergeError?: React.ReactNode
  /** Label on the merge button. Defaults to "Merge". */
  mergeLabel?: string
  /** Who merged and into what, shown on a merged pull request. Defaults to the base branch. */
  mergedBy?: string
  onMerge?: () => void
  /** Shows "Ready for review" on a draft. */
  onReadyForReview?: () => void
  /** Called when a file in the expanded list is chosen. */
  onFileSelect?: (path: string) => void
  /** Link to the pull request. */
  href?: string
  /** Checks list open state. Opens by itself when a check fails. */
  checksOpen?: boolean
  defaultChecksOpen?: boolean
  onChecksOpenChange?: (open: boolean) => void
  /** Static skeleton while the pull request loads. */
  loading?: boolean
  /** `card` draws its own surface, `plain` sits inside yours, `compact` is one line for chat lists. */
  variant?: "card" | "plain" | "compact"
  /** Extra controls at the start of the footer. */
  actions?: React.ReactNode
}

type DiffLineKind = "context" | "add" | "remove"

/** A piece of a changed line. `changed` pieces are the words that differ from the paired line. */
export interface DiffSegment {
  text: string
  changed: boolean
}

export interface DiffLine {
  kind: DiffLineKind
  text: string
  /** Line number in the old file. Set on context and removed lines. */
  oldNumber?: number
  /** Line number in the new file. Set on context and added lines. */
  newNumber?: number
  /** Word-level highlights, only on removed and added lines that pair up and look alike. */
  segments?: DiffSegment[]
}

export interface DiffHunk {
  /** Stable id from the hunk position, for example `h-40-42`. */
  id: string
  oldStart: number
  oldLines: number
  newStart: number
  newLines: number
  /** The text after the second `@@`, usually the enclosing function. */
  heading?: string
  lines: DiffLine[]
  additions: number
  deletions: number
  /** False while a streamed hunk is still arriving. */
  complete: boolean
}

interface DiffSource {
  old: string[]
  new: string[]
  /** Whether the old text ended with a newline, kept by `applyHunks`. */
  oldEol: boolean
  newEol: boolean
}

export interface DiffFile {
  path: string
  /** Previous path, set on renames. */
  oldPath?: string
  status: DiffFileStatus
  hunks: DiffHunk[]
  additions: number
  deletions: number
  binary?: boolean
  /** Both full versions, when known. Lets a viewer expand collapsed unchanged lines. */
  source?: DiffSource
  /** False while a streamed patch is still writing this file. */
  complete: boolean
}

/** Totals across files, for a review header. */
function diffStats(files: ReadonlyArray<Pick<DiffFile, "additions" | "deletions">>) {
  let additions = 0
  let deletions = 0
  for (const file of files) {
    additions += file.additions
    deletions += file.deletions
  }
  return { files: files.length, additions, deletions }
}

type ChecksSummary = ReturnType<typeof summarizeChecks>

interface MergeGate {
  allowed: boolean
  /** Why Merge is not available, in words. */
  reason?: React.ReactNode
  tone: "ready" | "blocked" | "conflict"
}

const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`

/** "Ines", "Ines and Tomas", "Ines, Tomas and 2 others". */
function joinNames(names: string[]) {
  if (names.length <= 1) return names[0] ?? ""
  if (names.length === 2) return `${names[0]} and ${names[1]}`
  if (names.length === 3) return `${names[0]}, ${names[1]} and ${names[2]}`
  return `${names[0]}, ${names[1]} and ${names.length - 2} others`
}

/** Decides whether Merge is offered, and if not, the one sentence that says why. */
export function mergeGate(props: {
  status: PullRequestStatus
  baseBranch: string
  mergeable?: PullRequestMergeable
  blockedReason?: React.ReactNode
  canMerge?: boolean
  checks: ChecksSummary
  review?: PullRequestReview
}): MergeGate {
  const { status, baseBranch, mergeable, blockedReason, canMerge, checks, review } = props
  if (status === "draft")
    return {
      allowed: false,
      tone: "blocked",
      reason: "This is a draft. Mark it ready for review before merging.",
    }
  if (status !== "open") return { allowed: false, tone: "blocked" }
  if (mergeable === "conflicts")
    return {
      allowed: false,
      tone: "conflict",
      reason: `This branch has conflicts with ${baseBranch}. Resolve them, then merge.`,
    }
  if (canMerge === true) return { allowed: true, tone: "ready" }
  if (mergeable === "blocked" || canMerge === false)
    return {
      allowed: false,
      tone: "blocked",
      reason: blockedReason ?? "Branch protection blocks merging. Ask a maintainer to merge.",
    }
  if (checks.requiredFailed > 0)
    return {
      allowed: false,
      tone: "conflict",
      reason: `${plural(checks.requiredFailed, "required check")} ${
        checks.requiredFailed === 1 ? "is" : "are"
      } failing. Fix or rerun ${checks.requiredFailed === 1 ? "it" : "them"} to merge.`,
    }
  if (checks.requiredWaiting > 0)
    return {
      allowed: false,
      tone: "blocked",
      reason: `Waiting for ${plural(checks.requiredWaiting, "required check")} to finish.`,
    }
  if (review?.state === "changes-requested")
    return {
      allowed: false,
      tone: "blocked",
      reason: review.reviewers?.length
        ? `${joinNames(review.reviewers)} requested changes. Address the review to merge.`
        : "Changes were requested. Address the review to merge.",
    }
  if (review?.state === "review-required")
    return { allowed: false, tone: "blocked", reason: "An approving review is required to merge." }
  return { allowed: true, tone: "ready" }
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

