/* -------------------------------------------------------------------------------------------------
 * Small parts
 * -----------------------------------------------------------------------------------------------*/

const STATUS: Record<
  PullRequestStatus,
  { label: string; tone: string; icon: React.ComponentType<{ className?: string }> }
> = {
  open: { label: "Open", tone: "text-(color:--chatcn-green)", icon: GitPullRequestIcon },
  // No dedicated draft or closed pull request glyphs in the set yet: the word carries the state.
  draft: { label: "Draft", tone: "text-(color:--chatcn-fg-subtle)", icon: GitPullRequestIcon },
  merged: { label: "Merged", tone: "text-(color:--chatcn-purple)", icon: GitMergeIcon },
  closed: { label: "Closed", tone: "text-(color:--chatcn-red)", icon: GitPullRequestIcon },
}

/* -------------------------------------------------------------------------------------------------
 * Skeleton
 * -----------------------------------------------------------------------------------------------*/

function Bar({ className }: { className: string }) {
  return <span className={cn("bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) block", className)} />
}

function PullRequestSkeleton({ compact }: { compact?: boolean }) {
  if (compact)
    return (
      <span className="flex h-full w-full items-center gap-2.5">
        <Bar className="size-4 rounded-full" />
        <Bar className="h-2.5 w-2/5" />
        <span className="flex-1" />
        <Bar className="h-2.5 w-16" />
      </span>
    )
  return (
    <div role="status" aria-busy="true" aria-label="Loading pull request">
      <div className="flex gap-2.5 px-3.5 pt-3.5 pb-3">
        <Bar className="mt-0.5 size-4 rounded-full" />
        <div className="flex flex-1 flex-col gap-2.5 pt-1">
          <Bar className="h-3 w-3/5" />
          <Bar className="h-2.5 w-2/5" />
        </div>
      </div>
      <div className="border-(color:--chatcn-border) flex flex-col border-t">
        {["w-1/3", "w-1/4", "w-2/5"].map((w) => (
          <div
            key={w}
            className="border-(color:--chatcn-border) flex h-10 items-center gap-2.5 border-b px-3.5 last:border-b-0"
          >
            <Bar className="size-4 rounded-full" />
            <Bar className={cn("h-2.5", w)} />
          </div>
        ))}
      </div>
    </div>
  )
}

/** Status glyph. Swaps with the kit's blur crossfade, so open to merged reads as one object. */
function PullRequestGlyph({ status }: { status: PullRequestStatus }) {
  const { icon: Icon, tone } = STATUS[status]
  return (
    <span
      data-slot="pull-request-glyph"
      className={cn("grid size-4 shrink-0 place-items-center [&_svg]:size-4", tone)}
    >
      <span
        key={status}
        className="grid place-items-center motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]"
      >
        <Icon aria-hidden="true" />
      </span>
    </span>
  )
}

