type ChecksPhase = "none" | "failed" | "running" | "pending" | "passed"

/** The worst state among the checks that matter. Optional checks still waiting never hold it up. */
function checksPhase(s: ChecksSummary, total: number): ChecksPhase {
  if (total === 0) return "none"
  if (s.failed) return "failed"
  if (s.requiredWaiting === 0) return "passed"
  return s.running ? "running" : "pending"
}

function checksText(s: ChecksSummary, total: number): { label: string; detail?: string } {
  const phase = checksPhase(s, total)
  const waiting = s.running + s.pending
  const skipped = s.skipped ? `, ${s.skipped} skipped` : ""
  if (phase === "none") return { label: "No checks" }
  if (phase === "passed")
    return waiting
      ? {
          label: "All required checks passed",
          detail: `${s.passed} passing, ${waiting} optional pending${skipped}`,
        }
      : { label: "All checks passed", detail: `${plural(s.passed, "check")}${skipped}` }
  const parts: string[] = []
  if (s.failed) parts.push(`${s.failed} failing`)
  if (waiting) parts.push(`${waiting} pending`)
  if (s.passed) parts.push(`${s.passed} passing`)
  return { label: parts.join(", ") }
}

