/**
 * A pull request an agent opened, with the merge box under it: status, branches, author, the
 * change totals with the five-cell bar, checks (failing first), review and whether it can merge.
 * Merge is only offered when the host would allow it; otherwise the card says why in words.
 */
export function PullRequestCard({
  title,
  number,
  status,
  repo,
  branch,
  baseBranch = "main",
  author,
  meta,
  files,
  stats,
  checks = [],
  review,
  mergeable,
  blockedReason,
  canMerge,
  merging = false,
  mergeError,
  mergeLabel = "Merge",
  mergedBy,
  onMerge,
  onReadyForReview,
  onFileSelect,
  href,
  checksOpen: checksOpenProp,
  defaultChecksOpen,
  onChecksOpenChange,
  loading = false,
  variant = "card",
  actions,
  className,
  ...props
}: PullRequestCardProps) {
  const summary = React.useMemo(() => summarizeChecks(checks), [checks])
  const sorted = React.useMemo(() => sortChecks(checks), [checks])
  const totals = files ? diffStats(files) : stats
  const gate = mergeGate({
    status,
    baseBranch,
    mergeable,
    blockedReason,
    canMerge,
    checks: summary,
    review,
  })
  const reasonId = React.useId()

  // Uncontrolled checks list opens itself when a check fails, the moment you need to look.
  const [checksOpenState, setChecksOpenState] = React.useState(
    defaultChecksOpen ?? summary.failed > 0,
  )
  const checksOpen = checksOpenProp ?? checksOpenState
  const prevFailed = React.useRef(summary.failed)
  React.useEffect(() => {
    if (summary.failed > prevFailed.current && checksOpenProp === undefined)
      setChecksOpenState(true)
    prevFailed.current = summary.failed
  }, [summary.failed, checksOpenProp])
  const setChecksOpen = (next: boolean) => {
    if (checksOpenProp === undefined) setChecksOpenState(next)
    onChecksOpenChange?.(next)
  }

  const isCompact = variant === "compact"
  const surface =
    variant === "card"
      ? "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) overflow-hidden forced-colors:outline-1 forced-colors:outline-solid"
      : variant === "compact"
        ? "rounded-(--chatcn-radius-md) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-xs) forced-colors:outline-1 forced-colors:outline-solid"
        : undefined

  const announcement =
    status === "merged"
      ? `Pull request ${number} merged`
      : status === "closed"
        ? `Pull request ${number} closed`
        : mergeError
          ? `Merge of pull request ${number} failed`
          : ""

  /* ----------------------------------------------------------------------------- compact */
  if (isCompact) {
    const label = `${STATUS[status].label} pull request ${number}${repo ? ` in ${repo}` : ""}`
    const inner = loading ? (
      <PullRequestSkeleton compact />
    ) : (
      <>
        <PullRequestGlyph status={status} />
        <span className="sr-only">{label}: </span>
        <span className="flex min-w-0 flex-1 items-baseline gap-2">
          <span className="text-[0.8125rem]/[1.25rem] min-w-0 truncate font-medium">{title}</span>
          <span
            aria-hidden="true"
            className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 font-mono tabular-nums @max-[24rem]/pr:hidden"
          >
            #{number}
          </span>
          {/* The repo is left out of the line: a list of rows names it once, above. */}
        </span>
        {checks.length > 0 && (status === "open" || status === "draft") ? (
          <CheckCounts summary={summary} />
        ) : null}
        {totals ? <DiffCounts additions={totals.additions} deletions={totals.deletions} /> : null}
      </>
    )
    return (
      <div
        data-slot="pull-request-card"
        data-variant="compact"
        data-pull-request-state={loading ? "loading" : status}
        aria-busy={loading || undefined}
        // A narrow row gives its room to the title: the number and passing count step aside.
        className={cn(
          "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) @container/pr relative min-w-0",
          surface,
          className,
        )}
        {...props}
      >
        {href && !loading ? (
          <a
            href={href}
            target="_blank"
            rel="noreferrer"
            className={cn(
              "rounded-(--chatcn-radius-md) flex h-10 min-w-0 items-center gap-2.5 ps-3 pe-3 outline-none pointer-coarse:h-11",
              "ease-(--chatcn-ease-standard) hover:bg-(color:--chatcn-alpha-100) transition-colors duration-150",
              "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
            )}
          >
            {inner}
          </a>
        ) : (
          <div className="flex h-10 min-w-0 items-center gap-2.5 ps-3 pe-3 pointer-coarse:h-11">
            {inner}
          </div>
        )}
      </div>
    )
  }

  /* ----------------------------------------------------------------------------- card */
  if (loading) {
    return (
      <div
        data-slot="pull-request-card"
        data-variant={variant}
        data-pull-request-state="loading"
        className={cn("text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg)", surface, className)}
        {...props}
      >
        <PullRequestSkeleton />
      </div>
    )
  }

  const open = status === "open"
  const phase = checksPhase(summary, checks.length)
  const checkLine = checksText(summary, checks.length)
  const showChecks = checks.length > 0 && status !== "closed"
  const reviewers = review?.reviewers ?? []

  const reviewRow =
    review && (open || status === "draft") ? (
      <div data-slot="pull-request-review" data-review-state={review.state} className={rowBase}>
        <RowGlyph state={review.state}>
          {review.state === "approved" ? (
            <CircleCheckIcon aria-hidden="true" className="text-(color:--chatcn-green)" />
          ) : review.state === "changes-requested" ? (
            <CircleAlertIcon aria-hidden="true" className="text-(color:--chatcn-amber)" />
          ) : review.state === "commented" ? (
            <MessageSquareIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle)" />
          ) : (
            <CircleDashedIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle)" />
          )}
        </RowGlyph>
        <RowText
          label={
            review.state === "approved"
              ? "Approved"
              : review.state === "changes-requested"
                ? "Changes requested"
                : review.state === "commented"
                  ? "Reviewed with comments"
                  : "Review required"
          }
          detail={
            reviewers.length
              ? review.state === "review-required"
                ? `Waiting on ${joinNames(reviewers)}`
                : `by ${joinNames(reviewers)}`
              : undefined
          }
        />
      </div>
    ) : null

  let mergeRow: React.ReactNode = null
  if (status === "merged") {
    mergeRow = (
      <div data-slot="pull-request-merge" className={rowBase}>
        <RowGlyph state="merged">
          <GitMergeIcon aria-hidden="true" className="text-(color:--chatcn-purple)" />
        </RowGlyph>
        <RowText
          label={
            <>
              Merged into <span className="font-mono">{baseBranch}</span>
            </>
          }
          detail={mergedBy ? `by ${mergedBy}` : undefined}
        />
      </div>
    )
  } else if (status === "closed") {
    mergeRow = (
      <div data-slot="pull-request-merge" className={rowBase}>
        <RowGlyph state="closed">
          <CircleMinusIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle)" />
        </RowGlyph>
        <RowText label="Closed without merging" detail={mergedBy ? `by ${mergedBy}` : undefined} />
      </div>
    )
  } else if (merging) {
    mergeRow = (
      <div data-slot="pull-request-merge" className={rowBase}>
        <RowGlyph state="merging">
          <Spinner className="text-(color:--chatcn-blue) size-4" />
        </RowGlyph>
        <span className="text-[0.8125rem]/[1.25rem] py-2.5">
          <ShimmerText>
            Merging into <span className="font-mono">{baseBranch}</span>
          </ShimmerText>
        </span>
      </div>
    )
  } else if (mergeError) {
    mergeRow = (
      <div data-slot="pull-request-merge" className={rowBase}>
        <RowGlyph state="error">
          <CircleXIcon aria-hidden="true" className="text-(color:--chatcn-red)" />
        </RowGlyph>
        <RowText label="Merge failed" detail={<span id={reasonId}>{mergeError}</span>} />
      </div>
    )
  } else if (open || status === "draft") {
    mergeRow = (
      <div data-slot="pull-request-merge" data-merge-gate={gate.tone} className={rowBase}>
        <RowGlyph state={gate.allowed ? "ready" : gate.tone}>
          {gate.allowed ? (
            <CircleCheckIcon aria-hidden="true" className="text-(color:--chatcn-green)" />
          ) : gate.tone === "conflict" ? (
            <CircleXIcon aria-hidden="true" className="text-(color:--chatcn-red)" />
          ) : (
            <CircleAlertIcon aria-hidden="true" className="text-(color:--chatcn-amber)" />
          )}
        </RowGlyph>
        <RowText
          label={
            gate.allowed
              ? "Ready to merge"
              : gate.tone === "conflict"
                ? mergeable === "conflicts"
                  ? "Conflicts"
                  : "Checks failing"
                : "Merging blocked"
          }
          detail={
            gate.allowed ? (
              `No conflicts with ${baseBranch}`
            ) : (
              <span id={reasonId} data-slot="pull-request-merge-reason">
                {gate.reason}
              </span>
            )
          }
        />
      </div>
    )
  }

  const canShowMerge = open && onMerge !== undefined
  const hasFooter = Boolean(
    href || actions || canShowMerge || (status === "draft" && onReadyForReview),
  )

  return (
    <div
      data-slot="pull-request-card"
      data-variant={variant}
      data-pull-request-state={merging ? "merging" : status}
      className={cn("text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) min-w-0", surface, className)}
      {...props}
    >
      {/* Header: glyph, title and number, then status, repo, author and branches. */}
      <div className="flex gap-2.5 ps-3.5 pe-2 pt-3 pb-3">
        <span className="flex h-5 items-center">
