/** An agent's pull request, green and approved. Merge runs for a moment, then the card settles. */
function PullRequestCardDemo() {
  const [status, setStatus] = React.useState<PullRequestStatus>("open")
  const [merging, setMerging] = React.useState(false)

  React.useEffect(() => {
    if (merging) {
      const id = window.setTimeout(() => {
        setMerging(false)
        setStatus("merged")
      }, 1600)
      return () => window.clearTimeout(id)
    }
    if (status === "merged") {
      // Replays so the preview never ends on a dead card.
      const id = window.setTimeout(() => setStatus("open"), 5000)
      return () => window.clearTimeout(id)
    }
  }, [merging, status])

  return (
    <PullRequestCard
      className="w-full max-w-xl"
      title="Paginate the runs list"
      number={482}
      status={status}
      repo="brightwell/console"
      branch="feat/runs-pagination"
      baseBranch="main"
      author={agentAuthor}
      meta="opened 6 min ago"
      files={agentChange}
      checks={passingChecks}
      review={{ state: "approved", reviewers: ["Ines Duarte"] }}
      merging={merging}
      mergeLabel="Squash and merge"
      mergedBy={status === "merged" ? "Ines Duarte" : undefined}
      href={PR_HREF}
      onMerge={() => setMerging(true)}
    />
  )
}

